sudo tee /etc/nginx/conf.d/port-6700.conf >/dev/null <<'ANTRIEB_NGINX'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;

    location = / {
        default_type text/plain;
        return 200 "nginx is serving on port 6700\n";
    }

    location / {
        return 404;
    }
}
ANTRIEB_NGINX
sudo chmod 0644 /etc/nginx/conf.d/port-6700.conf
sudo restorecon -v /etc/nginx/conf.d/port-6700.conf
sudo nginx -t

